/**
 * What the pipeline should produce from the accumulated spectra.
 *
 * Not independently valid: "stokes" needs two polarizations, which the
 * Siglent cannot provide (one trace per sweep). Validate against the
 * driver's declared capabilities, not in isolation — see
 * radio_control.driver.SpectrumDriver.capabilities.
 */
export interface DataProcessingSettings {
  output_format?: "raw_spectra" | "power_spectral_density" | "flux_density" | "brightness_temperature" | "stokes";
  time_resolution_seconds?: number | null;
}
/**
 * What a driver can produce, so an impossible output format is rejected
 * at validation rather than three hours in.
 *
 * A model and not part of the ABC because it has to be *sent* — a plan
 * editor greys out "stokes" on a single-polarization receiver, and an ABC
 * has nothing to serialize.
 *
 * `driver` overlaps the settings discriminator but answers a different
 * question: settings say which receiver they're for, this says which is
 * attached. The frame's config only exists after a sweep completes.
 */
export interface DriverCapabilities {
  driver: "specan" | "rfsoc";
  /**
   * 1 for the Siglent's single trace; stokes needs 2.
   */
  polarizations: number;
  supported_output_formats: (
    "raw_spectra" | "power_spectral_density" | "flux_density" | "brightness_temperature" | "stokes"
  )[];
}
/**
 * Every span currently claimed, across all plans.
 *
 * Owned by the command-handler thread — single writer, no locking. The
 * status thread publishes a snapshot rather than reading this.
 */
export interface Timeline {
  spans?: Span[];
}
